verification_commands.ac3:
set -u
command -v python3 >/dev/null || { echo "ac3 RED: python3 missing"; exit 1; }
test -f docs/state/merge_test_index.json || { echo "ac3 RED: docs/state/merge_test_index.json missing"; exit 1; }
python3 - <<'PYEOF' || exit 1
import hashlib, json, os, sys
A = "docs/state/outputs/t120_definer_gate_amendment.json"
if not os.path.exists(A):
    sys.stderr.write("ac3 RED: %s missing - this card changes the topology that legs 5 and 161 assert, and a card that breaks two shipped gates without writing down what it broke is how a green merge produces a red suite\n" % A); raise SystemExit(1)
rec = json.load(open(A, encoding="utf-8"))
if rec.get("card") != "t120":
    sys.stderr.write("ac3 RED: the record does not belong to card t120\n"); raise SystemExit(1)
if rec.get("applied_by") != "orchestrator" or rec.get("card_writes_index_bytes") is not False:
    sys.stderr.write("ac3 RED: the record must declare applied_by=orchestrator and card_writes_index_bytes=false - the index is orchestrator-owned\n"); raise SystemExit(1)
if rec.get("status") not in ("proposed", "ratified"):
    sys.stderr.write("ac3 RED: the record must be labelled proposed (or ratified once the orchestrator rules)\n"); raise SystemExit(1)
if rec.get("policy") != "W2 eight-property index-amendment policy (WAL 1248), invoked IN WRITING":
    sys.stderr.write("ac3 RED: the record must state IN WRITING that the W2 eight-property policy is invoked - this amendment changes index bytes and cannot be implicit\n"); raise SystemExit(1)
if rec.get("re_premise_not_relax") is not True:
    sys.stderr.write("ac3 RED: the record must declare re_premise_not_relax true - legs 5 and 161 are re-premised to the four-pipeline reality, never relaxed or deleted\n"); raise SystemExit(1)
if rec.get("no_leg_deleted") is not True or rec.get("verifier_thresholds_touched") is not False:
    sys.stderr.write("ac3 RED: the record must state that no leg is deleted and no verifier threshold is touched\n"); raise SystemExit(1)
if rec.get("ready_script_resurrected") is not False:
    sys.stderr.write("ac3 RED: the record must state ready_script_resurrected=false - F3a: docs/state/amend_index_entry6_phase7.cjs.ready stays dead\n"); raise SystemExit(1)
if rec.get("chosen_shape") != "F4 HYBRID (leg 5 name-list exclusion gains promote.yml; generator re-premised to the four-name set PLUS the human-gate property; leg 161 predicate re-premised; leg 183 unamended)":
    sys.stderr.write("ac3 RED: the record must state the chosen shape VERBATIM (F4's 'choose once' requirement) so no later card can claim a different vocabulary for the same fact\n"); raise SystemExit(1)
am = rec.get("amendments")
if not isinstance(am, list) or sorted(int(e["index"]) for e in am) != [5, 161]:
    sys.stderr.write("ac3 RED: the record carries amendments for %s, not exactly {5, 161} - leg 183 needs NO index edit (its command carries no workflow literal), and a record that edits it anyway is editing bytes it does not need to touch\n" % sorted(int(e["index"]) for e in am)); raise SystemExit(1)
noop = rec.get("leg183_noop_attestation")
if not isinstance(noop, dict):
    sys.stderr.write("ac3 RED: the record must carry the leg-183 NO-OP attestation (command sha, entry sha, and the literals measured absent) - 'we did not touch it' has to be a recorded measurement, not silence\n"); raise SystemExit(1)
tests = json.load(open("docs/state/merge_test_index.json", encoding="utf-8"))["tests"]
def esha(e): return hashlib.sha256(json.dumps(e, separators=(",", ":")).encode("utf-8")).hexdigest()
def csha(s): return hashlib.sha256(s.encode("utf-8")).hexdigest()
def apply_regions(pairs, direction, leg):
    # the regions are RAW substrings of the decoded command (tests[i]["command"] is already
    # JSON-decoded), so the replacement is plain string work; json.dumps'ing both sides would
    # search for a needle wearing the entry's own quote characters and match nothing
    out = tests[leg]["command"]
    for r in pairs:
        needle = r["from"] if direction == "forward" else r["to"]
        repl = r["to"] if direction == "forward" else r["from"]
        if out.count(needle) != 1:
            sys.stderr.write("ac3 RED: a replaced_region %s text is not unique in the live leg %s command - the record does not describe the shipped bytes\n" % ("from" if direction == "forward" else "to", leg)); raise SystemExit(1)
        out = out.replace(needle, repl, 1)
    return out
# leg 183's no-op attestation is checked against the LIVE index, in whichever state we are in
t183 = tests[183]
if noop.get("command_sha256") != csha(t183["command"]) or noop.get("entry_sha256") != esha(t183):
    sys.stderr.write("ac3 RED: the leg-183 no-op attestation does not match the live index (%s / %s) - either the index moved under the record or the attestation was copied from a different tree\n" % (csha(t183["command"])[:16], esha(t183)[:16])); raise SystemExit(1)
for lit in noop.get("workflow_literals_absent_from_command", []):
    if lit in t183["command"]:
        sys.stderr.write("ac3 RED: the no-op attestation claims %r is absent from leg 183's command but it is present - leg 183's healing is claimed to need no index write, and that claim is exactly this check\n" % lit); raise SystemExit(1)
states = []
for e in am:
    leg = int(e["index"])
    cmd = tests[leg]["command"]
    regions = e.get("replaced_regions", [])
    if not regions:
        sys.stderr.write("ac3 RED: leg %s carries no replaced_regions - the edit must be reconstructible byte-for-byte, never pasted from a snapshot\n" % leg); raise SystemExit(1)
    if csha(cmd) == e["old_command_sha256"]:
        if esha(tests[leg]) != e.get("entry_sha_before"):
            sys.stderr.write("ac3 RED: the index still holds the OLD leg %s command but the entry sha moved - the entry was edited outside the record\n" % leg); raise SystemExit(1)
        built = apply_regions(regions, "forward", leg)
        if csha(built) != e.get("new_command_sha256"):
            sys.stderr.write("ac3 RED: applying leg %s replaced_regions forward does not reproduce new_command_sha256 - the record does not describe the intended edit\n" % leg); raise SystemExit(1)
        # reverse: apply the same regions in reverse to the BUILT command
        rev = built
        for r in regions:
            needle = r["to"]; repl = r["from"]
            if rev.count(needle) != 1:
                sys.stderr.write("ac3 RED: a leg %s 'to' region is not unique in the built command - the record is not losslessly reversible\n" % leg); raise SystemExit(1)
            rev = rev.replace(needle, repl, 1)
        if rev != cmd:
            sys.stderr.write("ac3 RED: reversing leg %s replaced_regions out of the built command does not reproduce the shipped command - the record is not lossless\n" % leg); raise SystemExit(1)
        states.append("pre-amendment")
    elif csha(cmd) == e["new_command_sha256"]:
        if esha(tests[leg]) != e.get("entry_sha_after"):
            sys.stderr.write("ac3 RED: the index holds the SETTLED leg %s command but not the recorded entry sha - the amended entry drifted from the record\n" % leg); raise SystemExit(1)
        rev = cmd
        for r in regions:
            needle = r["to"]; repl = r["from"]
            if rev.count(needle) != 1:
                sys.stderr.write("ac3 RED: reversing leg %s: the 'to' region is not unique in the SETTLED command - the record does not describe the shipped bytes\n" % leg); raise SystemExit(1)
            rev = rev.replace(needle, repl, 1)
        if rev == cmd:
            sys.stderr.write("ac3 RED: reversing leg %s replaced_regions out of the SETTLED command changed nothing - the record does not describe the shipped bytes\n" % leg); raise SystemExit(1)
        states.append("post-amendment")
    else:
        sys.stderr.write("ac3 RED: the live leg %s command sha %s matches NEITHER old_command_sha256 nor new_command_sha256 - the index drifted under the amendment; STOP and request a re-groom\n" % (leg, csha(cmd)[:16])); raise SystemExit(1)
    # offsets are informational but must be truthful about the shipped bytes
    for r in regions:
        if r.get("offset_in_old_command") != cmd.find(r["from"]) and csha(cmd) == e["old_command_sha256"]:
            sys.stderr.write("ac3 RED: a leg %s region records offset_in_old_command=%s but the region sits at %s in the live command - the record's offsets are not measurements\n" % (leg, r.get("offset_in_old_command"), cmd.find(r["from"]))); raise SystemExit(1)
if len(set(states)) != 1:
    sys.stderr.write("ac3 RED: legs 5 and 161 are in DIFFERENT amendment states (%s) - a half-applied index is exactly the merge-window failure this record exists to prevent, and it is the failure mode that made leg 161 red in the first place\n" % states); raise SystemExit(1)
nc = rec.get("negative_control_matrix", [])
if len(nc) < 6:
    sys.stderr.write("ac3 RED: the record needs at least six negative-control legs (F4 demands both directions for every re-premised claim), found %d\n" % len(nc)); raise SystemExit(1)
badnc = [x.get("case") for x in nc if x.get("measured_rc") != x.get("expected_rc")]
if badnc:
    sys.stderr.write("ac3 RED: negative-control legs not as expected: %s\n" % badnc); raise SystemExit(1)
sys.stdout.write("ac3 evidence: byte proofs - both legs reconstruct forward AND reverse losslessly in the %s state; entry shas match the record; leg 183's no-op attestation matches the live entry and its %d named literals are absent\n" % (states[0], len(noop.get("workflow_literals_absent_from_command", []))))
sys.stdout.write("ac3 GREEN: THE AMENDMENT IS WRITTEN AND BYTE-PROVEN - %s prices legs 5 and 161 against the live index in the %s state (entry_sha_before/after, new_command_sha256, forward AND reverse), invokes the W2 eight-property policy in writing, names the chosen shape verbatim, attests leg 183 as a measured NO-OP, forbids resurrecting the phase-7 amend script, and carries a %d-leg negative-control matrix; the card itself writes zero index bytes\n" % (A, states[0], len(nc)))
PYEOF

