set -u
command -v python3 >/dev/null || { echo "ac6 RED: python3 missing - the DoD is three verbatim executions plus a set diff"; exit 1; }
test -f docs/state/merge_test_index.json || { echo "ac6 RED: docs/state/merge_test_index.json missing"; exit 1; }
A=docs/state/outputs/t120_definer_gate_amendment.json
