python3 - <<'PYEOF' || exit 1
import hashlib, json, subprocess, sys
rec = json.load(open("docs/state/outputs/t120_definer_gate_amendment.json", encoding="utf-8"))
tests = json.load(open("docs/state/merge_test_index.json", encoding="utf-8"))["tests"]
def csha(s): return hashlib.sha256(s.encode("utf-8")).hexdigest()
def esha(e): return hashlib.sha256(json.dumps(e, separators=(",", ":")).encode("utf-8")).hexdigest()
amap = {int(e["index"]): e for e in rec["amendments"]}
def command_for(i):
    """The command the DoD measures: the live one once the window has landed, the
    record-reconstructed one before it (so this fence is meaningful to the builder too)."""
    cmd = tests[i]["command"]
    if i not in amap:
        return cmd, "live"
    e = amap[i]
    if csha(cmd) == e["new_command_sha256"]:
        return cmd, "live(post-window)"
    if csha(cmd) != e["old_command_sha256"]:
        sys.stderr.write("ac6 RED: leg %s command sha %s matches neither recorded sha - the index drifted under the record; STOP and request a re-groom\n" % (i, csha(cmd)[:16])); raise SystemExit(1)
    built = cmd  # raw substring replacement, as in ac3/ac4
    for r in e["replaced_regions"]:
        if built.count(r["from"]) != 1:
            sys.stderr.write("ac6 RED: leg %s region not unique - cannot reconstruct the DoD command\n" % i); raise SystemExit(1)
        built = built.replace(r["from"], r["to"], 1)
    c = built
    if csha(c) != e["new_command_sha256"]:
        sys.stderr.write("ac6 RED: the reconstructed leg %s command is not the recorded one - the DoD would measure a fiction\n" % i); raise SystemExit(1)
    return c, "reconstructed(pre-window)"
bad = []
for i in (5, 161, 183):
    cmd, how = command_for(i)
    r = subprocess.run(["bash", "-c", cmd], capture_output=True, cwd=".", timeout=900)
    tail = (r.stdout.decode(errors="replace") + r.stderr.decode(errors="replace")).strip()[-160:].replace("\n", "|")
    if r.returncode != 0:
        bad.append("leg %d (%s) rc=%d: %s" % (i, how, r.returncode, tail))
    else:
        print("ac6 evidence: leg %d %s rc=0 - %s" % (i, how, tail[-110:]))
if bad:
    sys.stderr.write("ac6 RED: the card's own Definition of Done is not met:\n" + "".join("  - " + b + "\n" for b in bad) + "  (if the failing leg is 5 or 161 in the pre-window state, the reconstruction is broken - ac3's byte proof is the place to look; if it is leg 183, the generator/report/pin commit is incomplete, since leg 183 needs no index write at all)\n"); raise SystemExit(1)
print("ac6 evidence: all three carrier legs green - the RED set shrinks by exactly {5, 161, 183}")
PYEOF
